using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class SpatialGeometry {static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};public static object Run(){var s=SceneManager.GetActiveScene();var g=s.GetRootGameObjects().Single(x=>x.name.StartsWith("B5_Circular")).transform.Find("B5_Spatial_Refinement");var data=g.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().Select(m=>{int zero=0,micro=0;var v=m.vertices;var ts=m.triangles;float min=1;for(int i=0;i<ts.Length;i+=3){float a=Vector3.Cross(v[ts[i+1]]-v[ts[i]],v[ts[i+2]]-v[ts[i]]).sqrMagnitude;min=Mathf.Min(min,a);if(a<1e-22f)zero++;else if(a<1e-15f)micro++;}return new{m.name,zero,micro,min};}).ToArray();var result=new{meshes=data,props=g.Cast<Transform>().SelectMany(r=>r.Cast<Transform>()).Where(t=>t.GetComponentInChildren<Renderer>()).Select(t=>new{room=t.parent.name,t.name,center=V(t.GetComponentInChildren<Renderer>().bounds.center),size=V(t.GetComponentInChildren<Renderer>().bounds.size)})};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_B5_SpatialRefinement/geometry.json")),JsonConvert.SerializeObject(result,Formatting.Indented));return data.Where(x=>x.zero>0).ToArray();}}
